package ru.kstolu.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicInteger;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ChatUiTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;
 @Before public void setup(){ApiClient.configureForTests(url->{throw new AssertionError("No network: "+url);});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();}
 @After public void close(){controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private JSONObject item()throws Exception{return new JSONObject("{\"portions\":2,\"currency\":\"RUB\",\"recipe\":{\"status\":\"ok\",\"title\":\"Паста с томатами и шпинатом\",\"servings\":2,\"ingredients\":[{\"name\":\"Томаты\",\"amount\":200,\"unit\":\"g\"}],\"steps\":[{\"title\":\"Приготовьте соус\",\"body\":\"Прогрейте томаты.\"}]}}");}
 private View tag(Dialog d,String key){return d.getWindow().getDecorView().findViewWithTag(key);}
 private TextView find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return (TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView r=find(g.getChildAt(i),text);if(r!=null)return r;}}return null;}
 private int checkboxes(View v){int n=v instanceof CheckBox?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=checkboxes(((ViewGroup)v).getChildAt(i));return n;}
 private void layout(View v){v.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(844,View.MeasureSpec.EXACTLY));v.layout(0,0,390,844);}
 private void draw(View v,String name,int height)throws Exception{Bitmap b=Bitmap.createBitmap(390,height,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("build/visual-qa-1.1.2");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private int relativeBottom(View v,View ancestor){int bottom=v.getHeight();while(v!=ancestor){bottom+=v.getTop();v=(View)v.getParent();}return bottom;}
 @Test public void allQuickActionsFitWithoutCheckboxAndKeyboardMovesOnlyWhenVisible()throws Exception{
  SousChefSheet chat=new SousChefSheet(host,item(),()->0,()->0);chat.show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();View sheet=tag(d,"sous-sheet"),viewport=(View)sheet.getParent();layout(viewport);chat.applyViewport(0,24,0,24,0,false);layout(viewport);assertEquals(0,checkboxes(sheet));assertNotNull(find(sheet,"Заменить продукт"));assertNotNull(find(sheet,"Объяснить шаг"));assertNotNull(find(sheet,"Что-то пошло не так"));assertEquals(View.VISIBLE,tag(d,"sous-chips").getVisibility());assertTrue(relativeBottom(tag(d,"sous-input"),viewport)<=820);draw(viewport,"chat-actions",844);
  androidx.core.view.WindowInsetsCompat insets=new androidx.core.view.WindowInsetsCompat.Builder().setInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars(),androidx.core.graphics.Insets.of(0,24,0,24)).setInsets(androidx.core.view.WindowInsetsCompat.Type.ime(),androidx.core.graphics.Insets.of(0,0,0,320)).setVisible(androidx.core.view.WindowInsetsCompat.Type.ime(),true).build();androidx.core.view.ViewCompat.dispatchApplyWindowInsets(viewport,insets);layout(viewport);assertTrue(relativeBottom(tag(d,"sous-input"),viewport)<=524);assertEquals(View.GONE,tag(d,"sous-chips").getVisibility());draw(viewport,"chat-ime-insets",524);
  chat.applyViewport(0,24,0,24,0,false);layout(viewport);assertEquals(View.VISIBLE,tag(d,"sous-chips").getVisibility());assertTrue(relativeBottom(tag(d,"sous-input"),viewport)>524);d.dismiss();
 }
 @Test public void downwardDragClosesAndKeepsDraftWithoutCallingAi()throws Exception{new SousChefSheet(host,item(),()->0,()->0).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();layout((View)tag(d,"sous-sheet").getParent());((EditText)tag(d,"sous-input")).setText("Можно без масла?");View grip=tag(d,"sous-drag");long t=SystemClock.uptimeMillis();for(int[] a:new int[][]{{MotionEvent.ACTION_DOWN,10},{MotionEvent.ACTION_MOVE,150},{MotionEvent.ACTION_UP,150}}){MotionEvent e=MotionEvent.obtain(t,t+20,a[0],100,a[1],0);grip.dispatchTouchEvent(e);e.recycle();}assertFalse(d.isShowing());new SousChefSheet(host,item(),()->0,()->0).show();d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertEquals("Можно без масла?",((EditText)tag(d,"sous-input")).getText().toString());d.dismiss();}
 @Test public void shortDragDoesNotAccidentallyClose()throws Exception{new SousChefSheet(host,item(),()->0,()->0).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();layout((View)tag(d,"sous-sheet").getParent());View grip=tag(d,"sous-drag");for(int[] a:new int[][]{{MotionEvent.ACTION_DOWN,10},{MotionEvent.ACTION_MOVE,28},{MotionEvent.ACTION_UP,28}}){MotionEvent e=MotionEvent.obtain(0,20,a[0],100,a[1],0);grip.dispatchTouchEvent(e);e.recycle();}assertTrue(d.isShowing());d.dismiss();}
 @Test public void selectionStartsWithOneTapWithoutConfirmationDialog()throws Exception{
  AtomicInteger posts=new AtomicInteger();ApiClient.configureForTests(url->{posts.incrementAndGet();return new HttpURLConnection(url){public void disconnect(){}public void connect(){}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}public int getResponseCode(){return 200;}public InputStream getInputStream(){return new ByteArrayInputStream("{\"status\":\"done\",\"result\":{\"status\":\"not_food\",\"recipe\":{\"message\":\"Тестовый результат\"},\"recipes\":[]}}".getBytes(StandardCharsets.UTF_8));}};});java.lang.reflect.Field photo=MainActivity.class.getDeclaredField("productPhoto");photo.setAccessible(true);photo.set(host,new byte[]{1,2,3});find(host.getWindow().getDecorView(),"Подобрать блюда").performClick();for(int i=0;i<100&&posts.get()==0;i++){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertEquals(1,posts.get());assertNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());
 }
}
